import { createServer } from 'node:http';
const server = createServer((req, res) => res.end('ok'));
server.listen(3000, '127.0.0.1');
function shutdown() {
server.close(() => process.exit(0));
setTimeout(() => process.exit(0), 2000).unref();
}
process.on('SIGTERM', shutdown);

